def ic(name,small=False):return f'<svg class="icon{" sm" if small else ""}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{ICONS[name]}</svg>'
def href(page):return f'{page+1:02d}-{NAMES[page]}.html'
def link(label,page,kind='primary',extra=''):return f'<a class="btn {kind}" href="{href(page)}" {extra}>{label}</a>'
def btn(label,action,kind='primary',extra=''):return f'<button type="button" class="btn {kind}" data-action="{action}" {extra}>{label}</button>'
def badge(label,kind=''):return f'<span class="badge {kind}">{label}</span>'
def logo():return f'<a class="logo" href="{href(1)}" aria-label="JustStudy, início"><span class="logomark">{ic("book",True)}</span>juststudy<span class="accent">.</span></a>'
def steps(step):
    names=['Escolher','Focar','Explicar']
