    heading=f'<div class="page-title"><div><div class="eyebrow mb">{ "Página 01 / a escolha" if v=="caderno" else "Seu próximo estudo"}</div><h1>{title}</h1><p>Escolha o assunto. A gente encontra seu próximo tema.</p></div>{steps(0) if v=="ritual" else badge("Student · 875 créditos","neutral")}</div>'
    search=f'<div class="row between mb"><h3>{"Seus assuntos" if v=="estudio" else "Um ponto de partida"}</h3><div class="search" style="max-width:220px">{ic("search")}<input type="search" class="input" id="subject-search" aria-label="Buscar assunto" placeholder="Buscar assunto"></div></div>'
